int subarraySum(int[] nums, int k) {
  Map<Integer, Integer> counts = new HashMap<>();
  counts.put(0, 1);
  int prefix = 0, total = 0;
  for (int value : nums) {
    prefix += value;
    total += counts.getOrDefault(prefix - k, 0);
    counts.merge(prefix, 1, Integer::sum);
  }
  return total;
}

