def subarray_sum_prefix(nums, k):
    prefix = [0]
    for value in nums:
        prefix.append(prefix[-1] + value)
    total = 0
    for start in range(len(nums)):
        for end in range(start + 1, len(nums) + 1):
            if prefix[end] - prefix[start] == k:
                total += 1
    return total

