int ladderLength(String begin, String end, List<String> words) {
  Set<String> unused = new HashSet<>(words);
  Queue<String> queue = new ArrayDeque<>();
  queue.add(begin);
  for (int dist = 1; !queue.isEmpty(); dist++) {
    for (int size = queue.size(); size > 0; size--) {
      String word = queue.remove();
      if (word.equals(end)) return dist;
      char[] chars = word.toCharArray();
      for (int i = 0; i < chars.length; i++) {
        char old = chars[i];
        for (char c = 'a'; c <= 'z'; c++) { chars[i] = c; String next = new String(chars); if (unused.remove(next)) queue.add(next); }
        chars[i] = old;
      }
    }
  }
  return 0;
}

