def ladder_length_bi(begin, end, words):
    unused = set(words)
    if end not in unused:
        return 0
    front, back = {begin}, {end}
    dist = 1
    while front and back:
        if len(front) > len(back):
            front, back = back, front
        nxt_front = set()
        for word in front:
            for i in range(len(word)):
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    nxt = word[:i] + c + word[i+1:]
                    if nxt in back:
                        return dist + 1
                    if nxt in unused:
                        unused.remove(nxt)
                        nxt_front.add(nxt)
        front = nxt_front
        dist += 1
    return 0

