export function ladderLengthBi(begin: string, end: string, words: string[]): number {
  const unused = new Set(words);
  if (!unused.has(end)) return 0;
  let front = new Set([begin]);
  let back = new Set([end]);
  let dist = 1;
  while (front.size && back.size) {
    if (front.size > back.size) [front, back] = [back, front];
    const nextFront = new Set<string>();
    for (const word of front) for (let i = 0; i < word.length; i += 1) for (let c = 97; c <= 122; c += 1) {
      const next = word.slice(0, i) + String.fromCharCode(c) + word.slice(i + 1);
      if (back.has(next)) return dist + 1;
      if (unused.delete(next)) nextFront.add(next);
    }
    front = nextFront;
    dist += 1;
  }
  return 0;
}

