def median_partial_merge(a, b):
    total = len(a) + len(b)
    i = j = 0
    prev = cur = 0
    for _ in range(total // 2 + 1):
        prev = cur
        if j == len(b) or (i < len(a) and a[i] <= b[j]):
            cur = a[i]
            i += 1
        else:
            cur = b[j]
            j += 1
    return cur if total % 2 else (prev + cur) / 2

